     3	import hotel.reservations.Reservation;
     4	import hotel.reservations.ReservationStore;
     5	import hotel.rooms.Room;
     6	import hotel.rooms.Rooms;
     7	import java.time.LocalDate;
     8	import java.util.ArrayList;
     9	import java.util.Comparator;
    10	import java.util.List;
    11	import java.util.stream.Collectors;
    12	
    13	/** Which rooms are occupied on a given night, for the front desk (CSV). */
    14	public final class OccupancyReport {
    15	
    16	    private static final List<ReportColumn> COLUMNS = List.of(
    17	            new ReportColumn("room", (reservation, room) -> room.number()),
    18	            new ReportColumn("type", (reservation, room) -> room.type()),
    19	            new ReportColumn("reservation", (reservation, room) -> reservation.id()),
    20	            new ReportColumn("guest", (reservation, room) -> reservation.guest().name()),
    21	            new ReportColumn("check_in", (reservation, room) -> reservation.checkIn()),
    22	            new ReportColumn("check_out", (reservation, room) -> reservation.checkOut()));
    23	
    24	    private final Rooms rooms;
    25	    private final ReservationStore store;
    26	
    27	    public OccupancyReport(Rooms rooms, ReservationStore store) {
    28	        this.rooms = rooms;
    29	        this.store = store;
    30	    }
    31	
    32	    public String generate(LocalDate night) {
    33	        List<Reservation> occupying = new ArrayList<>();
    34	        for (Reservation reservation : store.all()) {
    35	            boolean coversNight = !reservation.checkIn().isAfter(night) && reservation.checkOut().isAfter(night);
    36	            if (reservation.isPaid() && coversNight) {
    37	                occupying.add(reservation);
    38	            }
    39	        }
    40	        occupying.sort(Comparator.comparingInt(Reservation::roomNumber));
    41	
    42	        StringBuilder csv = new StringBuilder();
    43	        csv.append(COLUMNS.stream().map(ReportColumn::header).collect(Collectors.joining(","))).append('\n');
    44	        for (Reservation reservation : occupying) {
    45	            Room room = rooms.find(reservation.roomNumber()).orElseThrow();
    46	            csv.append(COLUMNS.stream().map(column -> column.valueOf(reservation, room))
    47	                    .collect(Collectors.joining(","))).append('\n');
    48	        }
    49	        csv.append("total,").append(occupying.size()).append('/').append(rooms.all().size()).append('\n');
    50	        return csv.toString();
    51	    }
    52	}
