225	     9	/**
226	    10	 * The price of a stay: every night costs the room's nightly rate, plus the high-season surcharge on
227	    11	 * high-season nights; the rate plan may then give a discount on the sum. Money is rounded to cents
228	    12	 * (half-even) at every step.
229	    13	 */
230	    14	public final class PriceCalculator {
231	    15	
232	    16	    static final BigDecimal HIGH_SEASON_SURCHARGE = new BigDecimal("0.20");
233	    17	    static final BigDecimal NON_REFUNDABLE_DISCOUNT = new BigDecimal("0.15");
234	    18	
235	    19	    public Price calculate(Room room, LocalDate checkIn, LocalDate checkOut, RatePlan ratePlan) {
236	    20	        int nights = 0;
237	    21	        BigDecimal subtotal = cents(BigDecimal.ZERO);
238	    22	        for (LocalDate night = checkIn; night.isBefore(checkOut); night = night.plusDays(1)) {
239	    23	            subtotal = subtotal.add(nightPrice(room, night));
240	    24	            nights++;
241	    25	        }
242	    26	        BigDecimal discount = switch (ratePlan) {
243	    27	            case STANDARD -> cents(BigDecimal.ZERO);
244	    28	            case NON_REFUNDABLE -> cents(subtotal.multiply(NON_REFUNDABLE_DISCOUNT));
245	    29	        };
246	    30	        return new Price(nights, subtotal, discount, subtotal.subtract(discount));
247	    31	    }
248	    32	
249	    33	    BigDecimal nightPrice(Room room, LocalDate night) {
250	    34	        BigDecimal nightlyRate = room.nightlyRate();
251	    35	        if (isHighSeason(night)) {
252	    36	            return cents(nightlyRate.multiply(BigDecimal.ONE.add(HIGH_SEASON_SURCHARGE)));
253	    37	        }
254	    38	        return cents(nightlyRate);
255	    39	    }
256	    40	
257	    41	    /** High season: from December 15 to the end of February, and the whole of July. */
258	    42	    static boolean isHighSeason(LocalDate date) {
259	    43	        Month month = date.getMonth();
260	    44	        return month == Month.JANUARY
261	    45	                || month == Month.FEBRUARY
262	    46	                || month == Month.JULY
263	    47	                || (month == Month.DECEMBER && date.getDayOfMonth() >= 15);
264	    48	    }
265	    49	
266	    50	    static BigDecimal cents(BigDecimal value) {
267	    51	        return value.setScale(2, RoundingMode.HALF_EVEN);
268	    52	    }
269	    53	}
