417	    27	    public synchronized Reservation create(NewReservation request) {
418	    28	        if (!request.checkOut().isAfter(request.checkIn())) {
419	    29	            throw new HotelException(ErrorCode.INVALID_REQUEST, "check-out must be after check-in");
420	    30	        }
421	    31	        if (request.guests() < 1) {
422	    32	            throw new HotelException(ErrorCode.INVALID_REQUEST, "a reservation needs at least one guest");
423	    33	        }
424	    34	        Room room = rooms.find(request.roomNumber())
425	    35	                .orElseThrow(() -> new HotelException(
426	    36	                        ErrorCode.ROOM_NOT_FOUND, "room " + request.roomNumber() + " does not exist"));
427	    37	        if (request.guests() > room.capacity()) {
428	    38	            throw new HotelException(
